            # So check if any close_q index j satisfies i < j < limit
            for j in close_q_indices:
                if j > i and j < limit:
                    possible_swap = True
                    break
            if possible_swap:
                break

        if possible_swap:
            results.append("NO")
        else:
            results.append("YES")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
